for p in Path('../.private').glob('export-config-trial-*.json'):
 c=json.loads(p.read_text(encoding='utf-8'));r=ex.Redactor(c);sensitive.update(s for s,_ in r.literals);sensitive.update(s for s,_ in r.withhold_terms)
 if isinstance(c.get('version'),str):sensitive.add(c['version'])
paths=subprocess.check_output(['git','-c','core.excludesFile=','ls-tree','-rz','--name-only','605ea24']).decode().strip('\\0').split('\\0');texts={}
for rel in paths:
 try:texts[rel]=subprocess.check_output(['git','-c','core.excludesFile=','show','605ea24:'+rel]).decode('utf-8')
 except UnicodeDecodeError:pass
skip=[p for p in texts if p=='rounds/01-deliberation/prompt.md' or '/02-deliberation/packets/' in p]
base=set(line for p,t in texts.items() if p not in skip for line in t.splitlines());mult=collections.Counter(line for p in skip for line in set(texts[p].splitlines()))
missing=collections.defaultdict(list)
for rel in skip:
 for i,line in enumerate(texts[rel].splitlines(),1):
  if line.strip() and line not in base and mult[line]>1:missing[line].append(f'{rel}:{i}')
for line,refs in missing.items():
 for s in sorted(sensitive,key=len,reverse=True):
  if s:line=re.sub(re.escape(s),'[PRIVATE CONFIGURATION VALUE OMITTED]',line,flags=re.I)
 print(json.dumps({'line':line,'locations':refs}))
print(json.dumps({'distinct_uncovered_lines':len(missing),'occurrences':sum(map(len,missing.values()))}))
